function make_order(array $c,array $s,array $consent,string $lang):array{$d=$c['data'];$grantor=($c['route']==='death'||($d['forWhom']??'')==='other')?($d['applicantFirst'].' '.$d['applicantLast']):($d['firstName'].' '.$d['lastName']);$at=now();$ref=$c['order']['reference']??new_reference();$authority=authority_text($c,$s,$ref,$at,$lang);$o=['at'=>$at,'reference'=>$ref,'feeCents'=>3900,'consent'=>$consent,'authorityText'=>$authority,'declarations'=>(isset(rules()['situations'][$c['route']][$lang])?['situation'=>rules()['situations'][$c['route']][$lang]]:[])+rules()['declarations'][$lang],'settingsVersion'=>$s['version'],'permittedStartAt'=>$consent['early']?$at:'','language'=>$lang];foreach(['termsText','withdrawalText','privacyText','providerName','providerAddress','supportEmail','iban','bic','beneficiary','authorityMethod'] as $k)$o[$k]=$s[$k];return $o;}
function new_reference():string{for($i=0;$i<20;$i++){$ref='RB-'.strtoupper(bin2hex(random_bytes(4)));if(!sql("SELECT 1 FROM rb_records WHERE kind='case' AND JSON_UNQUOTE(JSON_EXTRACT(data_json,'$.order.reference'))=? LIMIT 1",[$ref])->fetch())return $ref;}fail('REFERENCE_UNAVAILABLE',503);}
function document_html(array $c,bool $authority=false):string{$o=$c['order'];if(!$o)fail('ORDER_REQUIRED');$html='<!doctype html><html lang="'.h($o['language']).'"><head><meta charset="utf-8"><style>body{font-family:Noto Sans,sans-serif;font-size:10pt;color:#182a47;line-height:1.5}h1{font-size:21pt}h2{font-size:13pt;margin-top:22px}p{white-space:normal;overflow-wrap:anywhere}h2{page-break-after:avoid}tr{page-break-inside:avoid}th,td{vertical-align:top;text-align:left;padding:5px;border-bottom:1px solid #e3e8ef}table{width:100%;border-collapse:collapse}footer{font-size:8pt;margin-top:30px}</style></head><body><h1>Rundfunkbeitrag Support</h1><h2>'.h($o['reference']).'</h2>';
 if(!$authority){$html.='<h2>Serviceauftrag / Service order</h2><p>'.h(rules()['routes'][$c['route']]['title'][$o['language']]).'<br>'.number_format(($o['feeCents']??4000)/100,2,',','').' EUR · '.h($o['at']).'</p><h2>Anbieter / Provider</h2><p>'.h($o['providerName']).'<br>'.nl2br(h($o['providerAddress'])).'</p><h2>Banküberweisung / Bank transfer</h2><p>'.h($o['beneficiary']).'<br>IBAN: '.h($o['iban']).'<br>BIC: '.h($o['bic']).'<br>Verwendungszweck / Reference: '.h($o['reference']).'</p>'.(($qr=girocode_data_uri($o))?'<p><img src="'.$qr.'" width="140" height="140" alt="GiroCode"><br>GiroCode: mit der Banking-App scannen, alle Angaben werden übernommen. / Scan with your banking app to fill in the transfer.</p>':'').'<h2>Ihre Angaben / Your information</h2><table>';foreach(field_set($c['route'],$c['data'])['fields'] as $f){$v=$c['data'][$f['key']]??'';if($v===''||$v===[])continue;if(isset($f['options'])){foreach($f['options'] as [$code,$label])if($v===$code){$v=$label[$o['language']];break;}}$html.='<tr><th>'.h($f['label'][$o['language']]).'</th><td>'.h(is_array($v)?implode(', ',$v):$v).'</td></tr>';}$html.='</table><h2>Erklärungen / Declarations</h2>';foreach($o['declarations'] as $key=>$label)$html.='<p>'.(!empty($o['consent'][$key])?'Zugestimmt / Accepted: ':'Nicht verlangt / Not requested: ').h($label).'</p>';foreach(['termsText'=>'Servicebedingungen / Service terms','withdrawalText'=>'Widerruf / Withdrawal','privacyText'=>'Datenschutz / Privacy'] as $key=>$title)$html.='<h2>'.h($title).'</h2><p>'.nl2br(h($o[$key])).'</p>';}
 $html.='<h2>Vollmacht / Authorisation</h2><p>'.nl2br(h($o['authorityText'])).'</p><p>Datum / Date: __________________<br>Unterschrift / Signature: __________________</p><footer>Wir sind nicht mit ARD, ZDF, Deutschlandradio oder Beitragsservice verbunden. Receiving an order, submitting an application and the official decision are separate steps.</footer></body></html>';return $html;}
function pdf_bytes(string $html):string{require_once private_root().'/vendor/autoload.php';$options=new Dompdf\Options();$options->set('isRemoteEnabled',false);$options->set('isPhpEnabled',false);$options->set('isJavascriptEnabled',false);$coverage=array_flip(json_decode(file_get_contents(__DIR__.'/fonts/coverage.json'),true));foreach(preg_split('//u',strip_tags(html_entity_decode($html,ENT_QUOTES,'UTF-8')),-1,PREG_SPLIT_NO_EMPTY) as $char){if(!in_array($char,["\n","\r","\t"],true)&&!isset($coverage[mb_ord($char,'UTF-8')]))fail('PDF_USE_HTML',422);}$options->set('defaultFont','Noto Sans');$options->set('tempDir',private_root().'/data/tmp');$options->set('fontCache',private_root().'/data/fonts');$options->set('chroot',private_root().'/data');foreach(['tmp','fonts'] as $d)if(!is_dir(private_root().'/data/'.$d))mkdir(private_root().'/data/'.$d,0700,true);$dompdf=new Dompdf\Dompdf($options);$font=private_root().'/data/fonts/NotoSans.ttf';if(!is_file($font)){copy(__DIR__.'/fonts/NotoSans.ttf',$font);chmod($font,0600);}$dompdf->getFontMetrics()->registerFont(['family'=>'Noto Sans','style'=>'normal','weight'=>'normal'],$font);$dompdf->getFontMetrics()->registerFont(['family'=>'Noto Sans','style'=>'normal','weight'=>'bold'],$font);$dompdf->loadHtml($html,'UTF-8');$dompdf->setPaper('A4');$dompdf->render();return $dompdf->output();}
function download(string $content,string $mime,string $name):never{if(db()->inTransaction())db()->commit();header('Content-Type: '.$mime);header("Content-Disposition: attachment; filename*=UTF-8''".rawurlencode($name));header('Cache-Control: private, no-store');header("Content-Security-Policy: default-src 'none'; sandbox");echo $content;exit;}
